                event.priority = parts[8].isEmpty() ? 0 : Integer.parseInt(parts[8]);
                event.resourceRequestCpu = parts[9].isEmpty() ? 0 : Double.parseDouble(parts[9]);
                event.resourceRequestRam = parts[10].isEmpty() ? 0 : Double.parseDouble(parts[10]);
                event.resourceRequestLocalDisk = parts[11].isEmpty() ? 0 : Double.parseDouble(parts[11]);
                event.differentMachineConstraint = parts[12].isEmpty() ? 0 : Integer.parseInt(parts[12]);
                sourceContext.collectWithTimestamp(event, event.timestamp);
            }
        }
    }

